def _validate_exit_code_map(self):
    """Validate exit_code_map — must be a JSON array of two-element [condition, exit_code] pairs.

    Validation rules (only when the field is non-empty):
    - Must parse as valid JSON.
    - Parsed result must be a list.
    - Each entry must be a two-element list.
    - entry[0] (condition_str): if not "default", must contain "=".
    - entry[1] (exit_val): must be a non-negative integer (not a bool).
    """
    if self.exit_code_map is None:
        return
    raw: str = self.exit_code_map.value if self.exit_code_map.value else ""
    if not raw.strip():
        return

    try:
        parsed = json.loads(raw)
    except (json.JSONDecodeError, ValueError) as exc:
        err = DataValidationError(
            f"ERROR: exit_code_map is not valid JSON: {exc}"
        )
        extension_manager.add_error(err, field="exit_code_map")
        return

    if not isinstance(parsed, list):
        err = DataValidationError("ERROR: exit_code_map must be a JSON array")
        extension_manager.add_error(err, field="exit_code_map")
        return

    for idx, entry in enumerate(parsed):
        if not isinstance(entry, list) or len(entry) != 2:
            err = DataValidationError(
                f"ERROR: exit_code_map entry {idx} must be a two-element array"
            )
            extension_manager.add_error(err, field="exit_code_map")
            continue

        condition_str = entry[0]
        exit_val = entry[1]

        if condition_str != "default" and "=" not in str(condition_str):
            err = DataValidationError(
                f"ERROR: exit_code_map entry {idx} condition must be in "
                f"question_id=value format"
            )
            extension_manager.add_error(err, field="exit_code_map")

        if isinstance(exit_val, bool) or not isinstance(exit_val, int) or exit_val < 0:
            err = DataValidationError(
                f"ERROR: exit_code_map entry {idx} exit code must be a non-negative integer"
            )
            extension_manager.add_error(err, field="exit_code_map")
